```swift
import Foundation

class NewsFeed {
    // Define a struct to hold news article data
    struct NewsArticle {
        let title: String
        let description: String
        let author: String
        let publicationDate: Date
        let content: String
    }

    // Define a class to manage the news feed
    class NewsFeedManager {
        var newsArticles: [NewsArticle] = []

        // Function to add a new news article
        func addNewsArticle(title: String, description: String, author: String, content: String) {
            let newsArticle = NewsArticle(title: title, description: description, author: author, publicationDate: Date(), content: content)
            newsArticles.append(newsArticle)
        }

        // Function to get the latest news articles
        func getLatestNews() -> [NewsArticle] {
            return newsArticles.sorted(by: { $0.publicationDate < $1.publicationDate })
        }

        // Function to get news articles for a specific demographic
        func getNewsForDemographic(demographic: String) -> [NewsArticle] {
            return newsArticles.filter { $0.author.contains(demographic) }
        }
    }

    // Function to update the news feed with a new news article
    func updateNewsFeed(newArticle: NewsArticle) {
        newsArticles.append(newArticle)
    }

    // Function to display the news feed
    func displayNewsFeed() {
        print("News Feed:")
        for article in newsArticles {
            print("Title: \(article.title), Author: \(article.author), Date: \(article.publicationDate), Content: \(article.content)")
        }
    }
}

// Example usage:
let newsFeed = NewsFeed()
let newsArticle1 = NewsArticle(title: "New Tax Reform Proposal", description: "A new tax reform proposal has been introduced in the government.", author: "John Doe", publicationDate: Date(), content: "This is a sample article.")
newsFeed.addNewsArticle(title: "Tax Reform", description: "This is another article.", author: "Jane Doe", content: "This is another sample article.")

